import heapq


def pass_route(n: int, edges: list[list[int]], stations: list[list[int]], prices: list[int]) -> int:
    if n == 0:
        return -1
    if n == 1:
        return 0

    zone_count = len(prices)
    mask_count = 1 << zone_count

    adj = [[] for _ in range(n)]
    for u, v, cost, zone in edges:
        if 0 <= u < n and 0 <= v < n:
            bit = (1 << zone) if 0 <= zone < zone_count else 0
            adj[u].append((v, cost, bit))
            adj[v].append((u, cost, bit))

    offers = [set() for _ in range(n)]
    for stop, zone in stations:
        if 0 <= stop < n and 0 <= zone < zone_count:
            offers[stop].add(zone)
    offers = [list(zones) for zones in offers]

    INF = 10**30
    dist = [INF] * (n * mask_count)
    dist[0] = 0

    heap = [(0, 0, 0)]
    target = n - 1

    while heap:
        d, u, mask = heapq.heappop(heap)
        idx = u * mask_count + mask
        if d > dist[idx]:
            continue

        if u == target:
            return d

        base = u * mask_count

        for zone in offers[u]:
            bit = 1 << zone
            if not (mask & bit):
                new_mask = mask | bit
                nd = d + prices[zone]
                nidx = base + new_mask
                if nd < dist[nidx]:
                    dist[nidx] = nd
                    heapq.heappush(heap, (nd, u, new_mask))

        for v, cost, bit in adj[u]:
            if bit and (mask & bit):
                nd = d
            else:
                nd = d + cost

            nidx = v * mask_count + mask
            if nd < dist[nidx]:
                dist[nidx] = nd
                heapq.heappush(heap, (nd, v, mask))

    return -1
